        "ticker": "NSIT",
        "category": 1,
        "company": "Insight Enterprises는 기업 고객 대상 IT 하드웨어·소프트웨어 유통 및 클라우드·데이터센터·AI 인프라 관련 전문 서비스를 제공하는 Solutions Integrator다. 매출의 상당 부분이 기업 IT 조달(디바이스·서버·네트워크 장비 재판매)과 클라우드·AI 인프라 구축 서비스에서 발생하며, 최근 분기 매출성장률이 14.73%→1.16%→-1.18%(q0/q1/q2)로 둔화되던 국면에서 2분기 실적이 재가속하며 밸류에이션 리레이팅이 진행 중이다.",
        "volumeExplanation": "2026년 8월 6일 발표된 2분기 실적에서 EPS 3.86달러(컨센서스 2.93달러 상회)와 매출 24.0억 달러(+14.7% YoY)를 기록하며 시장 예상을 크게 상회했다(SEC 8-K item 2.02, 2026-08-06). 이후 9월 들어 Zacks Strong Buy 상향, Needham Overweight 상향, JPMorgan·Raymond James의 목표주가 인상 등 애널리스트 전망 상향이 이어지며, VOL_X 3.44·주간 거래량배수 3.43의 거래량 급증이 나타났다.",
