        "company": "ITT는 Motion Technologies(마찰재·EV 브레이크 패드), Industrial Process(펌프·밸브, 에너지·화학 플랜트향), Connect & Control Technologies(항공우주·방산·산업용 커넥터) 3개 세그먼트로 구성된 다각화 산업재 제조업체다. 완성차 OEM(EV 브레이크 마찰재), 에너지·화학 플랜트, 항공우주·방산 고객을 기반으로 하며, 최근 3개 분기 매출성장률(YoY)이 51.49%→32.74%→13.46%로 둔화되는 국면에서 영업이익률은 12.24%→11.65%→16.95%로 최근 분기 레버리지가 개선된 모습이다.",
        "volumeExplanation": "2026년 8월6일 2Q26 실적(8-K item 2.02)에서 매출·EPS 서프라이즈와 FY26 가이던스 상향으로 주가가 5.4% 상승했으나, 이는 이번 VOL_X(2.12) 측정 시점(9월 중순)과 6주 이상 시차가 있어 직접 촉매로 보기 어렵다. 9월 들어 나온 뉴스는 동종업계 대비 주가·밸류에이션을 비교하는 Zacks 기사 정도로, 신규 실적·계약·정책 발표 같은 명확한 단일 촉매는 확인되지 않는다. 8월6일 실적 발표 이후 추가 8-K 공시도 없어 VOL_X 2.12·주간 거래량배수 1.95를 설명할 뚜렷한 표면적 뉴스는 없다.",
